// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MultiplicatorX4} from "../src/MultiplicatorX4.sol";

contract InvMutTest is Test {
    MultiplicatorX4 c;
    function setUp() public { c = new MultiplicatorX4(); }

    function testFuzz_property(uint256 amt, bytes memory payload) public {
        amt = bound(amt, 0, 1 ether);

        Receiver r = new Receiver();

        vm.deal(address(this), amt);

        bool ok;
        try c.Command(address(r), payload) {
            ok = true;
        } catch {
            ok = false;
        }

        Receiver r2 = new Receiver();

        if (amt > 0) {
            c.Command{value: amt}(address(r2), payload);
        } else {
            c.Command{value: 0}(address(r2), payload);
        }

        assertTrue(r2.received() == amt);
    }
}

contract Receiver {
    uint256 public received;
    receive() external payable { received += msg.value; }
    fallback() external payable { received += msg.value; }
}
